-- Coordinate proposte automaticamente per i luoghi del catasto: abbinamento
-- con il Dizionario del Repetti (repetti:abbina, docs/backend.md § 11.3) sul
-- dump di febbraio 2026, non ancora rivisto. Generata con
-- `db:import-luoghi -- abbinamenti.csv --sql`.
--
-- Le righe gia' revisionate a mano (revisionato = 1) non vengono toccate:
-- le correzioni si importano con `db:import-luoghi`.

ON DUPLICATE KEY UPDATE lat = IF(revisionato = 1, lat, VALUES(lat)), lng = IF(revisionato = 1, lng, VALUES(lng)), certezza = IF(revisionato = 1, certezza, VALUES(certezza)), nome_moderno = IF(revisionato = 1, nome_moderno, VALUES(nome_moderno)), fonte = IF(revisionato = 1, fonte, VALUES(fonte)), chiave_nomi = IF(revisionato = 1, chiave_nomi, VALUES(chiave_nomi)), note = IF(revisionato = 1, note, VALUES(note)), revisionato = IF(revisionato = 1, revisionato, VALUES(revisionato));

